# Import of required libraries
import skyramp
import json
import os
import re
import time

from SkyrampUtils import create_category, create_recipe, update_recipe, get_recipes_list


# URL for test requests
URL_localhost = skyramp.get_base_url("SKYRAMP_TEST_BASE_URL", "http://localhost:9000")


def test_integration():
    # Invocation of Skyramp Client
    client = skyramp.Client()
    # Definition of authentication header
    headers = {}
    if os.getenv("SKYRAMP_TEST_TOKEN") is not None:
        headers["Authorization"] = "Bearer " + os.getenv("SKYRAMP_TEST_TOKEN")

    # Declaration of variables
    categories_only = "true"
    page = "1"
    perPage = "100"

    categories_POST_response = create_category(
        client, headers, skyramp.unique_suffix("Removal Cat")
    )

    assert re.match(
        r"^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$",
        skyramp.get_response_value(categories_POST_response, "id"),
        re.IGNORECASE,
    )
    assert skyramp.get_response_value(categories_POST_response, "name").startswith("Removal Cat")
    assert skyramp.get_response_value(categories_POST_response, "slug") is not None

    category_id = skyramp.get_response_value(categories_POST_response, "id")
    category_slug = skyramp.get_response_value(categories_POST_response, "slug")
    category_name = skyramp.get_response_value(categories_POST_response, "name")

    removal_recipe_name = skyramp.unique_suffix("Removal Recipe")
    recipes_POST_response = create_recipe(client, headers, removal_recipe_name)

    # POST /api/recipes returns the new recipe slug as a bare JSON string
    recipes = json.loads(recipes_POST_response.response_body)
    assert isinstance(recipes, str) and recipes.startswith("removal-recipe")

    recipes_recipes_PATCH_response = update_recipe(
        client,
        headers,
        recipes,
        [{"id": category_id, "name": category_name, "slug": category_slug}],
        name=removal_recipe_name,
    )

    assert skyramp.get_response_value(recipes_recipes_PATCH_response, "name") == removal_recipe_name
    assert skyramp.get_response_value(recipes_recipes_PATCH_response, "slug") == recipes

    attached = json.loads(recipes_recipes_PATCH_response.response_body)["recipeCategory"]
    assert len(attached) == 1
    assert attached[0]["id"] == category_id
    assert attached[0]["slug"] == category_slug
    assert len(attached) == 1

    recipes_GET_response = get_recipes_list(
        client,
        headers,
        {
            "categories_only": [categories_only],
            "page": [page],
            "perPage": [perPage]
        },
    )

    listed = json.loads(recipes_GET_response.response_body)

    # the response reflects the pagination parameters that were sent
    assert listed["page"] == int(page)
    assert listed["per_page"] == int(perPage)
    assert len(listed["items"]) <= int(perPage)
    listed_slugs = [item["slug"] for item in listed["items"]]

    # While it holds a category, the recipe is part of the categories_only listing
    assert recipes in listed_slugs, (
        "a recipe with one category is missing from categories_only=true"
    )
    # and every recipe the filter returns really has at least one category
    assert all(item["recipeCategory"] for item in listed["items"]), (
        "categories_only=true returned a recipe with no category"
    )
    assert listed["total"] >= len(listed["items"]), (
        "total is smaller than the number of items on this page"
    )

    recipes_recipes_PATCH_1_response = update_recipe(
        client,
        headers,
        recipes,
        [],
        name=removal_recipe_name,
    )

    assert skyramp.get_response_value(recipes_recipes_PATCH_1_response, "slug") == recipes

    cleared = json.loads(recipes_recipes_PATCH_1_response.response_body)["recipeCategory"]
    assert cleared == [], "clearing recipeCategory did not remove the category"

    recipes_GET_1_response = get_recipes_list(
        client,
        headers,
        {
            "categories_only": [categories_only],
            "page": [page],
            "perPage": [perPage]
        },
    )

    listed_after = json.loads(recipes_GET_1_response.response_body)
    assert listed_after["page"] == int(page)
    assert listed_after["per_page"] == int(perPage)
    listed_after_slugs = [item["slug"] for item in listed_after["items"]]

    # Once its last category is gone the recipe must drop out of the listing
    assert recipes not in listed_after_slugs, (
        "recipe still listed by categories_only=true after its last category was removed"
    )
    assert all(item["recipeCategory"] for item in listed_after["items"]), (
        "categories_only=true returned a recipe with no category"
    )


if __name__ == "__main__":
    test_integration()
